# JSON

```json
{
  "limit": 50,
  "table": "email_message",
  "where": {
    "type": "and",
    "conditions": [
      {
        "op": "EXISTS",
        "type": "correlatedSubquery",
        "related": {
          "system": "client",
          "subquery": {
            "alias": "zsubq_member_states",
            "table": "email_message_member_state",
            "where": {
              "type": "and",
              "conditions": [
                {
                  "op": "=",
                  "left": {
                    "name": "direction",
                    "type": "column"
                  },
                  "type": "simple",
                  "right": {
                    "type": "literal",
                    "value": "OUTBOUND"
                  }
                },
                {
                  "type": "simple",
                  "left": {
                    "type": "column",
                    "name": "workspace_id"
                  },
                  "right": {
                    "type": "literal",
                    "value": null
                  },
                  "op": "="
                }
              ]
            },
            "orderBy": [
              [
                "id",
                "asc"
              ]
            ]
          },
          "correlation": {
            "childField": [
              "message_id"
            ],
            "parentField": [
              "id"
            ]
          }
        }
      },
      {
        "type": "simple",
        "left": {
          "type": "column",
          "name": "workspace_id"
        },
        "right": {
          "type": "literal",
          "value": null
        },
        "op": "="
      }
    ]
  },
  "orderBy": [
    [
      "id",
      "asc"
    ]
  ]
}
```

# Before

```
cat json | npx ast-to-zql
Warning: Unable to format output with prettier: SyntaxError: ';' expected. (1:137)
> 1 | query.email_message.whereExists('member_states', q => q.where('direction', 'OUTBOUND').where('workspace_id', null).orderBy('id', 'asc'))).where('workspace_id', null).orderBy('id', 'asc').limit(50)
```


# After

```
cat json | npx ast-to-zql
query.email_message
  .whereExists('member_states', q =>
    q
      .where('direction', 'OUTBOUND')
      .where('workspace_id', null)
      .orderBy('id', 'asc'),
  )
  .where('workspace_id', null)
  .orderBy('id', 'asc')
  .limit(50)
```
